style.css:
@-moz-document domain("docs.google.com") {
/* Background for the whole page */
  body, div.docs-texteventtarget-iframe, div.kix-appview-editor {
    background-color: #CFE1B9 !important;
  }

  /* Background behind the document */
  .kix-appview-editor, .docs-texteventtarget-iframe {
    background-color: #CFE1B9 !important;
  }

  /* Optional: Remove gray around page edges */
  .kix-page {
    background-color: white !important; /* Keep the page white for contrast */
    box-shadow: none !important;
  }
}
